-- Function: public.fn_get_inventory_balance
-- Backup generated on 2026-10-25 20:33:26

CREATE OR REPLACE FUNCTION public.fn_get_inventory_balance(p_product_id uuid, p_location_id uuid)  RETURNS TABLE(id uuid, material_product_id uuid, location_id uuid, total_stock integer, available_stock integer, reserved_stock integer, dispatched_stock integer, on_loan_stock integer, under_inspection_stock integer, under_cleaning_stock integer, damaged_stock integer, missing_stock integer, retired_stock integer, updated_at timestamp with time zone, product_name character varying, product_sku character varying, location_name character varying)  LANGUAGE sql  STABLE AS $function$     SELECT          b.id, b.material_product_id, b.location_id,         b.total_stock, b.available_stock, b.reserved_stock, b.dispatched_stock,         b.on_loan_stock, b.under_inspection_stock, b.under_cleaning_stock,         b.damaged_stock, b.missing_stock, b.retired_stock, b.updated_at,         p.name AS product_name, p.sku AS product_sku, l.name AS location_name     FROM inventory_balances b     JOIN material_products p ON b.material_product_id = p.id     JOIN inventory_locations l ON b.location_id = l.id     WHERE b.material_product_id = p_product_id AND b.location_id = p_location_id; $function$ ;
